/*
 * Icon/Benefit — Type=Line black/white 공용 글리프 데이터 (데이터 모듈)
 *
 * Figma 원본 (산출물 1)
 *   component set: https://www.figma.com/design/Ma09rS3GL9ahAGRADSWDj3/?node-id=19620-23774
 *   각 항목의 `node` 주석은 그 글리프의 vector 노드 ID다.
 *   Type=Line white 는 같은 지오메트리에 색만 다르므로 이 데이터를 공유한다.
 *
 * 색은 이 파일에 없다. 컴포넌트가 fill=currentColor 로 칠한다.
 *
 * ── 좌표계: 절대좌표가 아니라 글리프 로컬 좌표 + transform 이다 ──
 *
 *   Figma가 내보내는 SVG는 글리프 바운딩박스만 잘라낸 0 기준 좌표다.
 *   (예: membership 은 viewBox 0 0 50.4004 50.3994)
 *   컴포넌트는 viewBox "0 0 96 96" 으로 그리므로 프레임 안 제자리로 옮겨야 한다.
 *
 *   조립 에이전트에게 전달받은 전제는 "36개 전부 50.4 x 50.4 중앙 배치" 였으나,
 *   실제로 확인해 보니 **글리프 크기와 오프셋이 아이콘마다 다르다**
 *   (vip 60 x 40.8, point 67.2 x 67.2, vipInstallation 은 가로 중앙도 아니다).
 *   따라서 전역 상수 하나로는 표현할 수 없어 항목마다 transform 을 갖는다.
 *   값은 get_metadata 가 준 vector 노드의 x / y 를 그대로 옮긴 것이고,
 *   translate 뿐이라 배율은 1 이다 — 즉 획 두께가 왜곡되지 않는다.
 *
 *   d 문자열은 Figma 원본 그대로다. 좌표를 다시 계산하거나 단순화하지 않았다.
 *
 * ── 왜 string 이 아니라 구조체인가 ──
 *
 *   1. 36개 중 25개가 단일 path 가 아니다 (tradeInProgram 은 13개). 한 문자열로
 *      합치면 fill-rule 이 섞여 구멍이 잘못 뚫린다.
 *   2. path 마다 fill-rule 이 다르다. evenodd 인 path 가 64개, nonzero 가 74개다.
 *      전역으로 하나만 걸 수 없다.
 *   3. delivery / fastDelivery 두 개는 fill 에 더해 stroke 가 걸려 있다
 *      (Figma 원본이 그렇다). stroke 굵기는 BENEFIT_LINE_STROKE_WIDTH 다.
 *
 *   렌더 방법: glyph.paths 를 순서대로 <path d fillRule /> 로 그리고, 그 묶음을
 *   <g transform={glyph.transform}> 으로 감싼다. stroked 인 path 에만
 *   stroke=currentColor + strokeWidth=BENEFIT_LINE_STROKE_WIDTH 를 준다.
 */

/** 한 글리프를 이루는 path 하나. `d` 는 Figma 원본 문자열 그대로다. */
export interface BenefitLinePath {
  d: string
  /** Figma 원본의 fill-rule. 생략하면 구멍이 잘못 채워지는 path 가 있다. */
  fillRule: 'evenodd' | 'nonzero'
  /** true 면 fill 위에 stroke 도 그린다 (delivery / fastDelivery 뿐). */
  stroked?: boolean
}

export interface BenefitLineGlyph {
  /** 96 x 96 프레임 안 제자리로 옮기는 SVG transform. translate 전용(배율 1). */
  transform: string
  /** 문서 순서 그대로. 순서를 바꾸면 겹침이 달라진다. */
  paths: BenefitLinePath[]
}

/** 컴포넌트가 써야 할 viewBox. Figma variant 프레임 크기와 같다. */
export const BENEFIT_LINE_VIEWBOX = '0 0 96 96'

/** stroked path 의 굵기. Figma 원본 stroke-width 값이다(단위 없는 사용자 좌표). */
export const BENEFIT_LINE_STROKE_WIDTH = 1.6

